package com.quiz.servlet;
import com.quiz.dao.*; import com.quiz.model.*; import java.io.*; import java.sql.SQLException; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*;
@WebServlet("/assessment/start") public class AssessmentQuizServlet extends HttpServlet { private final QuizDAO dao=new QuizDAO(); private final ResultDAO results=new ResultDAO(); protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{int id=Integer.parseInt(req.getParameter("id"));User user=(User)req.getSession().getAttribute("user");Quiz quiz=dao.findPublishedById(id);if(quiz==null||quiz.isOverdue()||results.hasAssessmentAttempt(user.getId(),id)){resp.sendRedirect(req.getContextPath()+"/student/dashboard");return;}req.setAttribute("assessment",quiz);req.setAttribute("questions",dao.findQuestions(id));req.setAttribute("durationSeconds",quiz.getDurationMinutes()*60);req.setAttribute("submitPath","/assessment/submit");req.getRequestDispatcher("/WEB-INF/views/quiz.jsp").forward(req,resp);}catch(NumberFormatException e){resp.sendRedirect(req.getContextPath()+"/student/dashboard");}catch(SQLException e){throw new ServletException("Could not start assessment",e);}}}
